import{_ as e,o as s,c as t,a2 as r}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"跟做：任务恢复、尝试预算与管理员重试","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/job-recovery.md","filePath":"tutorials/job-recovery.md"}'),i={name:"tutorials/job-recovery.md"};function o(l,a,n,p,h,c){return s(),t("div",null,[...a[0]||(a[0]=[r(`<h1 id="跟做-任务恢复、尝试预算与管理员重试" tabindex="-1">跟做：任务恢复、尝试预算与管理员重试 <a class="header-anchor" href="#跟做-任务恢复、尝试预算与管理员重试" aria-label="Permalink to &quot;跟做：任务恢复、尝试预算与管理员重试&quot;">​</a></h1><p>从文档申请一次导出，然后以 Owner 或 Admin 登录，在首页打开“后台任务”。默认列出失败任务，可以切换到等待、执行中或已完成状态；打开一条记录，查看当前批次、尝试历史和安全错误摘要。</p><p>失败任务提供“重试失败任务”。这个操作保留原 Job ID 和业务请求，开启有限的新批次。旧记录继续可查；成功任务没有这个入口。业务 Handler 仍检查原请求者、凭据和源资源，因此重新执行不会恢复已经撤销的访问权。</p><h2 id="_1-为什么领取本身也消耗次数" tabindex="-1">1. 为什么领取本身也消耗次数 <a class="header-anchor" href="#_1-为什么领取本身也消耗次数" aria-label="Permalink to &quot;1. 为什么领取本身也消耗次数&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/74975dfcff42f07a516fcaafe8742ab578037b6b/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Core Jobs</a>在领取事务中增加 attempts，生成新的 lease_token，并记录这次尝试。随后即使进程立刻退出，次数也已经消耗。</p><p>租约过期后，下一个 Worker 可以重新领取尚有预算的任务。先前的尝试被记为 lease_expired；达到预算时，任务进入 failed，不再无限重领。临时错误进入 retry_wait，使用指数退避与 full jitter；永久错误直接失败。每个入队调用都明确给出有限的 <code>max_attempts</code>，数据库限制为 1–20。</p><p>知识库导出的 <code>EXPORT_JOB_MAX_ATTEMPTS</code> 默认是 5。它属于示例配置；替换业务时，新 Handler 使用自己的合理预算。详细设置见<a href="./../reference/config">生成配置参考</a>。</p><h2 id="_2-旧-worker-不能提交新结果" tabindex="-1">2. 旧 Worker 不能提交新结果 <a class="header-anchor" href="#_2-旧-worker-不能提交新结果" aria-label="Permalink to &quot;2. 旧 Worker 不能提交新结果&quot;">​</a></h2><p>每次领取都有独立的 token，续租、失败和成功都要求匹配当前 token 且仍在有效期内。成功在调用者事务中提交，业务结果、Job 和尝试历史共同完成。</p><p>例如，第一个 Worker 在上传后暂停，租约到期；第二个 Worker 接手并完成。第一个 Worker 即使继续运行，也不能凭旧 token 覆盖结果。Handler 可能重复执行，外部副作用需要自己的幂等策略；本示例使用不可覆盖的候选对象与唯一数据库发布来保护导出。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/74975dfcff42f07a516fcaafe8742ab578037b6b/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">Worker 循环</a>独立推进 Handler 和续租。如果续租 SQL 等待发布事务的行锁，Handler 仍能完成事务。续租失败时，先取消底层 Handler future、释放其事务，再写入失败状态；失败写入也有截止时间。两个真实 PostgreSQL 锁等待回归测试保护这个顺序。</p><p>关停先停止领取，给当前执行有限的完成时间。超时取消后保留 running 租约，等待自然过期恢复，不能提前把仍产生副作用的任务交给其他 Worker。已经开始的阻塞 ZIP 工作继续遵循上一章的协作取消与资源所有权规则。</p><h2 id="_3-新批次保留旧历史" tabindex="-1">3. 新批次保留旧历史 <a class="header-anchor" href="#_3-新批次保留旧历史" aria-label="Permalink to &quot;3. 新批次保留旧历史&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/74975dfcff42f07a516fcaafe8742ab578037b6b/migrations/0010_job_history.sql" target="_blank" rel="noreferrer">migration 0010</a>记录 JobBatch 与 JobAttempt。Job 指向当前批次，尝试记录保存编号、执行者、起止时间、租约截止时间及安全错误代码。领取、续租和终态变化在同一数据库事务更新相关记录。</p><p>从此前版本升级时，旧任务只保留当时可得的汇总；仍在运行的当前尝试会被记录，不伪造已经缺失的历史时间线。新产生的尝试则逐条记录。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/74975dfcff42f07a516fcaafe8742ab578037b6b/crates/app/src/modules/jobs/administration.rs" target="_blank" rel="noreferrer">管理员用例</a>按当前有效成员角色授权，只有 Owner/Admin 可以读取或重试。重试事务锁住失败 Job，建立下一批、重置有限预算，并一起写 Audit 和幂等记录；审计失败全部回滚。相同命令重复提交不会再开一批，并发请求也不能绕过状态约束。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/74975dfcff42f07a516fcaafe8742ab578037b6b/crates/app/src/modules/jobs/management.rs" target="_blank" rel="noreferrer">HTTP 入口</a>提供列表、详情及重试。列表使用与身份、状态过滤绑定的倒序游标；详情每页最多十批，支持读取更早记录。返回内容不包含 payload 或 lease_token，供管理员查看的是状态、错误摘要和关联请求。</p><h2 id="_4-前端如何接入恢复操作" tabindex="-1">4. 前端如何接入恢复操作 <a class="header-anchor" href="#_4-前端如何接入恢复操作" aria-label="Permalink to &quot;4. 前端如何接入恢复操作&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/74975dfcff42f07a516fcaafe8742ab578037b6b/packages/views/src/jobs/jobs-view.tsx" target="_blank" rel="noreferrer">共享任务 Views</a>通过生成 SDK 调用 Core API。Web 负责路由，View 用回调导航，知识库示例移除后这组管理页面仍保留。</p><p>正在运行的记录会刷新进度。请求失败时可重试同一命令；成功提交后回到最新历史，任务状态变化或权限被撤销后会刷新相关查询和 Session。普通成员看不到首页的管理入口，直接访问也会被后端拒绝。</p><p>错误摘要用于定位问题；原请求的关联 ID 可以继续用于后续审计和观测章节。管理员重试不会修改导出快照。原 Session 已失效或快照已经过期时，应由有权限的用户重新申请导出。</p><h2 id="_5-用可控故障验证" tabindex="-1">5. 用可控故障验证 <a class="header-anchor" href="#_5-用可控故障验证" aria-label="Permalink to &quot;5. 用可控故障验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exports</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/jobs.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>公开 Job/HTTP 测试使用真实 PostgreSQL 和同步点，覆盖：</p><ul><li>领取后崩溃也消耗预算，达到上限转 failed；</li><li>两个 Worker 接续执行，晚到的旧结果不发布；</li><li>临时重试按 scheduled_at 调度，业务参数保持不变；</li><li>关停有限等待且不提前释放租约；</li><li>管理员权限、有限新批次、历史、幂等及审计回滚；</li><li>发布遇到续租，以及续租超时后的事务释放。</li></ul><p>时限测试显式推进数据库中的租约/调度时间；竞态由 Notify 和真实锁等待组织，不用任意 sleep 碰时序。</p><p>关键旅程完成时运行一次真实浏览器：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/job-recovery.spec.ts</span></span></code></pre></div><p>隔离运行器使用较短但有限的测试预算。测试先暂停自己创建的 RustFS，观察导出正在运行，再强制终止本次运行器的 Worker；恢复存储，由运行器监督进程启动替代 Worker，验证导出接续完成。随后再次让存储不可用，等预算耗尽，通过实际管理员页面重试并观察成功与旧历史。</p><p>测试只操作自己的容器和进程，在 finally 中恢复存储并确认 Worker 健康。替代 Worker 由运行器统一管理，保持服务供同轮后续测试使用，整轮结束再统一关停。Worker 的临时根目录也按运行器隔离并清理；生产进程遭遇 SIGKILL 时，本地临时目录仍遵循上一章声明的清理边界。浏览器报告继续关闭敏感 trace/截图，只保留安全摘要。</p><p>默认 <code>just check</code> 不重复浏览器故障旅程。下一章会复用这些可靠任务来清理被删除的文档、附件和过期对象。</p><hr><p>源码版本：<code>74975dfcff42</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/74975dfcff42f07a516fcaafe8742ab578037b6b/docs/tutorials/11-job-recovery.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,33)])])}const k=e(i,[["render",o]]);export{b as __pageData,k as default};
